<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\SiteContent;use App\Services\ImageUploadService;use Illuminate\Http\{JsonResponse,Request};
class SiteContentController extends Controller{public function __construct(private ImageUploadService $images){}public function index():JsonResponse{return response()->json(['data'=>SiteContent::orderBy('group')->orderBy('sort_order')->get()->map(function($x){$x->image_url=$x->type==='image'&&$x->value?asset('storage/'.$x->value):null;return $x;})]);}public function update(Request $r,SiteContent $siteContent):JsonResponse{if($siteContent->type==='image'){$r->validate(['image'=>'required|image|mimes:jpg,jpeg,png,webp|max:5120']);$siteContent->update(['value'=>$this->images->replace($r->file('image'),$siteContent->value,'site')]);}else $siteContent->update($r->validate(['value'=>['nullable','string','max:10000']]));return response()->json(['data'=>$siteContent]);}}
